function OUT=G27V74R30D2R8_STANDALONE_CLONE(CTX,P,Tret,tauK,lambda,n)
% AUTO-GENERATED BY G27V74R30D2R8 FROM CURRENT AUTHORITATIVE SOURCES.
% No safety authority is claimed by this constructor.
if nargin<5 || isempty(lambda), lambda=0; end
J0=g27r30d2r8_old_shape_internal_jet(P,tauK,Tret);
J=J0;
if lambda~=0
    assert(nargin>=6 && isnumeric(n) && numel(n)==3 && all(isfinite(n(:))));
    n=double(n(:));
    J(:,1)=J(:,1)+double(lambda)*n;
end
CAND=g27r30d2r8_builder(CTX,P,Tret,tauK,J);
OUT=struct();
OUT.J0=J0;
OUT.J_internal=J;
OUT.candidate=CAND;
OUT.T_return=Tret;
OUT.tau_knot=tauK;
OUT.lambda=lambda;
end

function CAND=g27r30d2r8_builder(CTX,P,Tret,tauK,Jint)
% G27-V74R30B
% Build a 3-span payload reference:
%
%   span 1: t0 -> tm          existing UP correction
%   span 2: tm -> tm+tauK     local return segment 1
%   span 3: tm+tauK -> tm+Tret local return segment 2
%
% Each span is degree-15 and represented by DIRECT physical derivative
% Bernstein nets D0...D7.
%
% Correction physical jets:
%   at t0        : [0,0,...,0]
%   at tm        : [w,0,...,0]
%   at internal  : Jint(:,0...7)
%   at rejoin    : [0,0,...,0]
%
% The same Jint is used on both sides of the internal splice. Thus C7 is
% structural and is not imposed as a numerical equality constraint.
%
% Tret and tauK are decision variables of later stages. This builder makes
% NO safety claim by itself.

assert(isstruct(CTX)&&isfield(CTX,'request')&&isfield(CTX,'live'));
assert(isstruct(P)&&isfield(P,'generated')&&logical(P.generated));
assert(isfinite(Tret)&&Tret>0);
assert(isfinite(tauK)&&tauK>0&&tauK<Tret);
assert(isequal(size(Jint),[3 8])&&all(isfinite(Jint(:))));

v=double(CTX.live.active_payload_velocity_vector_m_s(:));
p0=double(CTX.request.xd_active(1:3));
t0=double(P.t0);
tm=double(P.tm);
w=double(P.displacement(:));

Tup=tm-t0;
pM=p0+v*Tup;

K=build_integer_maps();

Jzero=zeros(3,8);
Jpeak=zeros(3,8);
Jpeak(:,1)=w;

S(1)=make_span(t0,tm,p0,v,Jzero,Jpeak,K,'UP');
S(2)=make_span(tm,tm+tauK,pM,v,Jpeak,Jint,K,'RETURN_A');
pKnom=pM+v*tauK;
S(3)=make_span(tm+tauK,tm+Tret,pKnom,v,Jint,Jzero,K,'RETURN_B');

CAND=struct();
CAND.generated=true;
CAND.backend='BEZIER_D15_C7_TWOSEG_RETURN';
CAND.t0=t0;
CAND.tm=tm;
CAND.t1=tm+Tret;
CAND.T_return=Tret;
CAND.tau_knot=tauK;
CAND.J_internal=Jint;
CAND.spans=S;
CAND.span_count=3;
CAND.position_c7_structural=true;
CAND.derivative_order_available=7;
CAND.nominal_velocity=v;
CAND.active_reference_mode='NOMINAL';
CAND.shadow_only=true;
end


function S=make_span(ta,tb,pNomA,v,J0,J1,K,label)
h=tb-ta;

D=cell(8,1);
for r=0:7
    Dcorr=direct_derivative_control_net(K{r+1},J0,J1,h,r);

    if r==0
        n=size(Dcorr,2)-1;
        Dnom=zeros(3,n+1);
        for j=0:n
            Dnom(:,j+1)=pNomA+v*(h*j/n);
        end
        D{1}=Dnom+Dcorr;
    elseif r==1
        D{2}=Dcorr+v*ones(1,size(Dcorr,2));
    else
        D{r+1}=Dcorr;
    end
end

S=struct('ta',ta,'tb',tb,'T',h,'label',label, ...
    'D0',D{1},'D1',D{2},'D2',D{3},'D3',D{4}, ...
    'D4',D{5},'D5',D{6},'D6',D{7},'D7',D{8});
end


function D=direct_derivative_control_net(Kr,J0,J1,h,r)
n=15;
J=[double(J0);double(J1)];  % 6x8 is not what we want
Jvec=zeros(16,3);
for ax=1:3
    jax=[double(J0(ax,:)).';double(J1(ax,:)).'];
    s=zeros(16,1);
    for block=0:1
        for k=0:7
            idx=block*8+k+1;
            s(idx)=h^(k-r)/falling(n,k);
        end
    end
    Jvec(:,ax)=s.*jax;
end
D=(Kr*Jvec).';
end


function K=build_integer_maps()
n=15;

ME=zeros(16,16);
for k=0:7
    for r=0:k
        ME(k+1,r+1)=nchoosek(k,r);
        ME(n-k+1,8+r+1)=(-1)^r*nchoosek(k,r);
    end
end

K=cell(8,1);
F=eye(16);
K{1}=F*ME;

for r=1:7
    deg=n-r+1;
    F=deg*diff(F,1,1);
    K{r+1}=F*ME;
end
end


function f=falling(n,r)
if r==0
    f=1;
else
    f=prod(n-r+1:n);
end
end


function J=g27r30d2r8_old_shape_internal_jet(P,tau,T)
c=[ones(1,8),zeros(1,8)];
w=double(P.displacement(:));
u=tau/T;

J=zeros(3,8);
for r=0:7
    D=c;
    for k=1:r
        D=(numel(D)-1)*diff(D);
    end
    val=g27r30d2r8_decasteljau_scalar(D,u)/(T^r);
    J(:,r+1)=w*val;
end
end



function y=g27r30d2r8_decasteljau_scalar(c,u)
tmp=double(c(:)).';
while numel(tmp)>1
    tmp=(1-u)*tmp(1:end-1)+u*tmp(2:end);
end
y=tmp(1);
end

